t-weight: 600; transition: 0.3s; display: inline-block; }.slide-btn:hover { color: rgb(255, 255, 255); background: rgb(0, 0, 0); }.slider-nav { z-index: 10; gap: 10px; display: flex; position: absolute; bottom: 40px; left: 50%; transform: translate(-50%); }.nav-dot { cursor: pointer; background: rgb(184, 205, 217); border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; width: 32px; height: 4px; transition: 0.3s; }.nav-dot.active { background: rgb(13, 13, 13); }.slider-arrow { cursor: pointer; z-index: 10; background: rgba(255, 255, 255, 0.1); border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; border-radius: 50%; justify-content: center; align-items: center; width: 50px; height: 50px; transition: 0.3s; display: flex; position: absolute; top: 50%; transform: translateY(-50%); }.slider-arrow:hover { background: rgb(255, 255, 255); }.slider-arrow [class^="main-icon-"] { color: rgb(255, 255, 255); font-size: 30px; }.slider-arrow:hover [class^="main-icon-"] { color: rgb(115, 119, 171); }.slider-arrow.prev { left: 30px; }.slider-arrow.next { right: 30px; }@media (max-width: 1200px) {
